const app=document.querySelector('#app');
const safe=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const list=items=>`<ul>${items.map(item=>`<li>${safe(item)}</li>`).join('')}</ul>`;
const chosen=new Set();
const filters={query:'',sector:'all',stage:'all'};
const sectors=[...new Set(jobs.map(job=>job.sector))].sort((a,b)=>a.localeCompare(b,'es'));
const sourceLinks=job=>job.src.map(key=>`<a href="${sources[key].url}" target="_blank" rel="noopener">${safe(sources[key].label)} ↗</a>`).join('');
const jobUrl=job=>`/profesion/?id=${encodeURIComponent(job.id)}`;

function tile(job){const selected=chosen.has(job.id);const full=chosen.size===2&&!selected;return `<article class="card"><div class="card-top"><span class="job-icon" aria-hidden="true">${job.icon}</span><span class="sector-pill">${safe(job.sector)}</span></div><h3>${safe(job.name)}</h3><p>${safe(job.summary)}</p><div class="card-bottom"><a class="text-button" href="${jobUrl(job)}" aria-label="Ver ficha de ${safe(job.name)}">Ver ficha ↗</a><button class="compare-button ${selected?'selected':''}" data-choose="${job.id}" aria-pressed="${selected}" ${full?'disabled title="Quita una profesión para elegir otra"':''} aria-label="${selected?'Quitar':'Añadir'} ${safe(job.name)} ${selected?'de':'a'} la comparación">${selected?'− Quitar':full?'Máximo 2':'＋ Elegir'}</button></div></article>`}
function home(){return `<div class="home-view"><section class="hero"><div class="hero-copy"><p class="eyebrow">ORIENTACIÓN LABORAL · ESPAÑA</p><h1>¿Qué te gustaría <em>hacer?</em></h1><p class="lead">Busca profesiones o responde unas preguntas para encontrar ideas.</p><div class="home-actions"><a class="primary" href="/descubrir/">Responder preguntas ↗</a><a class="secondary-action" href="/explorar/">Ver ${jobs.length} profesiones ↗</a></div><div class="hero-foot"><span>FP y universidad</span><span class="divider"></span><span>Comunitat Valenciana</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="compass"><span>✦</span></div></div></section><section class="section home-featured"><div class="section-intro"><div><p class="eyebrow">PARA EMPEZAR</p><h2>Explora caminos.</h2></div><a class="section-link" href="/explorar/">Ver todas ↗</a></div><div class="cards">${[jobs[0],jobs[1],jobs[3],jobs[9]].map(tile).join('')}</div></section></div>`}
function filteredJobs(){const q=filters.query.trim().toLocaleLowerCase('es');return jobs.filter(job=>(filters.sector==='all'||job.sector===filters.sector)&&(filters.stage==='all'||job.stage.includes(filters.stage))&&(!q||[job.name,job.sector,job.summary,...job.tasks,...job.skills,...job.routes].join(' ').toLocaleLowerCase('es').includes(q)))}
function explorer(){return `<section class="section page-view explore"><div class="page-heading"><p class="eyebrow">EXPLORA</p><h1>Profesiones</h1><p>Busca por trabajo, sector o habilidad.</p></div><div class="controls"><label class="search"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="¿Qué te interesa?" autocomplete="off" aria-label="Buscar profesiones" value="${safe(filters.query)}"></label><label class="select-wrap">Sector <select id="sector"><option value="all">Todos</option>${sectors.map(name=>`<option value="${safe(name)}" ${filters.sector===name?'selected':''}>${safe(name)}</option>`).join('')}</select></label><label class="select-wrap">Etapa <select id="stage"><option value="all">Todas</option><option value="eso" ${filters.stage==='eso'?'selected':''}>ESO</option><option value="bach" ${filters.stage==='bach'?'selected':''}>Bachillerato</option><option value="fp" ${filters.stage==='fp'?'selected':''}>FP</option><option value="adulto" ${filters.stage==='adulto'?'selected':''}>Cambio profesional</option></select></label></div><div class="results-line"><strong id="count"></strong><div><a href="/descubrir/">No sé qué elegir ↗</a><a href="/comparar/">Comparar <span id="inline-count">(${chosen.size})</span> ↗</a></div></div><div id="cards" class="cards" aria-live="polite"></div><p id="empty" class="empty" hidden>Sin resultados. Prueba otra búsqueda.</p><p class="catalog-note">Fichas orientativas. <a href="/recursos/">Ver fuentes ↗</a></p></section>`}
function detail(job){if(!job)return `<section class="section page-view"><h1>No encontramos esa profesión.</h1><a class="primary" href="/explorar/">Volver al catálogo ↗</a></section>`;const full=chosen.size===2&&!chosen.has(job.id);const cv=job.valencia.length?`<div class="degree-list">${job.valencia.map(option=>`<a href="${option.url}" target="_blank" rel="noopener"><strong>${safe(option.degree)}</strong><span>${safe(option.uni)} · ${safe(option.type)} ↗</span></a>`).join('')}</div>`:'<p class="no-degree">Aún no hemos vinculado un grado concreto. Consulta la oferta de las universidades valencianas.</p>';return `<article class="section page-view detail-page"><a class="back-link" href="/explorar/">← Profesiones</a><div class="detail-hero"><div><p class="eyebrow">${safe(job.sector)} · FICHA ORIENTATIVA</p><h1>${safe(job.name)}</h1><p class="lead">${safe(job.summary)}</p><div class="detail-actions"><button class="primary button-primary" data-choose="${job.id}" ${full?'disabled title="Quita una profesión para elegir otra"':''}>${chosen.has(job.id)?'− Quitar de comparación':full?'Máximo 2':'＋ Elegir para comparar'}</button><a href="/comparar/">Ver comparación ↗</a></div></div><span class="detail-symbol" aria-hidden="true">${job.icon}</span></div><div class="detail-grid"><section><h2>Qué harías</h2>${list(job.tasks)}</section><section><h2>Habilidades</h2>${list(job.skills)}<p class="starter"><strong>Para empezar:</strong> ${safe(job.starter)}</p></section><section><h2>Entorno</h2><p>${safe(job.place)}</p><h3>Ten en cuenta</h3><p>${safe(job.watch)}</p></section><section><h2>Prueba el oficio</h2><p>${safe(job.first)}</p></section><section class="wide"><h2>Cómo llegar</h2>${list(job.routes)}${job.regulated?'<p class="warning">Profesión regulada: comprueba los requisitos oficiales de ejercicio.</p>':''}</section><section class="wide"><h2>Universidades valencianas</h2><p class="section-hint">Opciones verificadas; no es una lista completa ni garantiza admisión.</p>${cv}<a class="small-link" href="/recursos/">Ver las cinco universidades públicas ↗</a></section></div><div class="detail-sources"><strong>Fuentes</strong>${sourceLinks(job)}<small>Ficha editorial de ejemplo. Revisa requisitos y oferta actual en la institución.</small></div></article>`}
function comparison(){const selected=[...chosen].map(id=>jobs.find(job=>job.id===id));if(selected.length<2)return `<section class="section page-view compare-page"><div class="page-heading"><p class="eyebrow">COMPARA</p><h1>Elige dos profesiones</h1><p>${selected.length?'Ya tienes una. Elige otra para ver las diferencias.':'Empieza por dos trabajos que te interesen.'}</p></div><div class="compare-empty"><span aria-hidden="true">⇄</span>${selected.length?`<h2>${safe(selected[0].name)} + ¿cuál?</h2>`:'<h2>Dos opciones, una decisión mejor.</h2>'}<a class="primary" href="/explorar/">Elegir profesiones ↗</a></div></section>`;const [a,b]=selected;const detailLink=job=>`<a href="${jobUrl(job)}">Ver ficha ↗</a>`;const degreeCell=job=>job.valencia.length?job.valencia.map(option=>`<a href="${option.url}" target="_blank" rel="noopener">${safe(option.degree)} · ${safe(option.uni)} ↗</a>`).join(''):'<span>Sin opción concreta vinculada aún. <a href="/recursos/">Ver universidades ↗</a></span>';const rows=[['De qué va',job=>safe(job.summary)],['En el día a día',job=>list(job.tasks)],['Dónde se trabaja',job=>safe(job.place)],['Formación',job=>list(job.routes)],['Para ejercer',job=>job.regulated?'Profesión regulada. Consulta los requisitos oficiales.':'Requisitos variables según el puesto.'],['Habilidades',job=>list(job.skills)+`<small>Empieza por: ${safe(job.starter)}</small>`],['Primera prueba',job=>safe(job.first)],['Ten en cuenta',job=>safe(job.watch)],['Grados en la Comunitat',degreeCell]];return `<section class="section page-view compare-page"><div class="page-heading"><p class="eyebrow">COMPARA</p><h1>Frente a frente</h1><p>Lo importante para explorar tu siguiente paso.</p></div><div class="comparison-head"><div class="compare-label">CRITERIO</div>${[a,b].map(job=>`<div class="compare-job"><div><span class="job-icon">${job.icon}</span><span><small>${safe(job.sector)}</small><strong>${safe(job.name)}</strong></span></div><button data-choose="${job.id}" aria-label="Quitar ${safe(job.name)}">×</button>${detailLink(job)}</div>`).join('')}</div><div class="comparison-table">${rows.map(([label,value])=>`<div class="comparison-row"><h2>${label}</h2><div>${value(a)}</div><div>${value(b)}</div></div>`).join('')}</div><div class="compare-footer"><a href="/explorar/">Cambiar profesiones ↗</a><a href="/recursos/">Consultar fuentes ↗</a></div></section>`}
function resources(){return `<section class="section page-view resources-page"><div class="page-heading"><p class="eyebrow">FUENTES</p><h1>Estudios y datos</h1><p>Consulta la oferta oficial antes de decidir.</p></div><h2 class="resource-section-title">Universidades públicas valencianas</h2><div class="uni-grid">${universityCatalogs.map(uni=>`<a href="${uni.url}" target="_blank" rel="noopener"><strong>${safe(uni.name)}</strong><span>Oferta de grados ↗</span></a>`).join('')}</div><h2 class="resource-section-title">Otras fuentes</h2><div class="resource-grid"><a class="resource-card" href="${sources.families.url}" target="_blank" rel="noopener"><span class="resource-icon">01</span><h2>Formación Profesional</h2><p>Títulos y familias en TodoFP.</p><strong>Abrir TodoFP ↗</strong></a><a class="resource-card" href="${sources.needs.url}" target="_blank" rel="noopener"><span class="resource-icon">02</span><h2>Habilidades</h2><p>Necesidades formativas del SEPE.</p><strong>Abrir SEPE ↗</strong></a><a class="resource-card" href="https://www.ine.es/dynt3/inebase/index.htm?capsel=4568&padre=4563" target="_blank" rel="noopener"><span class="resource-icon">03</span><h2>Salarios</h2><p>Datos nacionales por grupos de ocupación.</p><strong>Abrir INE ↗</strong></a></div><p class="resource-note">Las opciones de grado vinculadas a las fichas son una selección, no toda la oferta. Las plazas y condiciones pueden cambiar cada curso.</p></section>`}
const mock=[{name:'Salud',views:142},{name:'Tecnología',views:104},{name:'Educación',views:78},{name:'Industria y energía',views:64},{name:'Otros sectores',views:92}];
const quizQuestions=[
 {title:'¿Qué disfrutas haciendo?',options:[{label:'Cuidar a alguien',tags:['cuidar','salud']},{label:'Arreglar cosas',tags:['arreglar','precision']},{label:'Crear algo nuevo',tags:['crear']},{label:'Organizar un plan',tags:['organizar']},{label:'Estar en la naturaleza',tags:['naturaleza']}]},
 {title:'¿Dónde te ves más a gusto?',options:[{label:'Con personas',tags:['gente']},{label:'En un taller',tags:['taller']},{label:'Ante una pantalla',tags:['pantalla']},{label:'Al aire libre',tags:['exterior']},{label:'En un laboratorio',tags:['laboratorio']}]},
 {title:'¿Qué reto te llama?',options:[{label:'Mejorar la salud',tags:['salud']},{label:'Enseñar o explicar',tags:['ensenar']},{label:'Resolver un problema técnico',tags:['arreglar']},{label:'Entender datos o pruebas',tags:['datos','ciencia']},{label:'Comunicar una idea',tags:['crear']}]},
 {title:'¿Qué forma de aprender explorarías?',options:[{label:'FP y práctica',tags:['fp']},{label:'Universidad',tags:['grado']},{label:'Cualquiera de las dos',tags:[]}]},
 {title:'¿Qué probarías esta semana?',options:[{label:'Una actividad con personas',tags:['gente','ensenar']},{label:'Construir o reparar',tags:['taller','arreglar']},{label:'Un proyecto digital',tags:['pantalla','crear']},{label:'Observar el entorno',tags:['exterior','naturaleza']},{label:'Investigar una pregunta',tags:['ciencia','precision']}]}];
const quizState={step:0,answers:[]};
function quizMatches(){const answered=quizState.answers.filter(Boolean);if(!answered.some(choice=>choice.tags.length))return ['electricidad','enfermeria','diseno','forestal','desarrollo'].map(id=>({job:jobs.find(job=>job.id===id),matches:[]}));return jobs.map(job=>({job,matches:answered.filter(choice=>choice.tags.some(tag=>job.tags.includes(tag)))})).filter(result=>result.matches.length).sort((a,b)=>b.matches.length-a.matches.length||a.job.name.localeCompare(b.job.name,'es')).slice(0,5)}
function discover(){const step=quizState.step;if(step>=quizQuestions.length){const suggestions=quizMatches();return `<section class="section page-view quiz-view"><div class="page-heading"><p class="eyebrow">DESCUBRIR</p><h1>Ideas para explorar</h1><p>Según tus respuestas, no según un perfil de personalidad.</p></div><div class="quiz-results">${suggestions.map(({job,matches})=>`<article class="quiz-result"><div class="quiz-result-title"><span class="job-icon">${job.icon}</span><div><small>${safe(job.sector)}</small><h2>${safe(job.name)}</h2></div></div><p>${safe(job.summary)}</p><div class="quiz-reasons"><strong>${matches.length?'Por qué aparece':'Una opción para empezar'}</strong><span>${matches.length?matches.map(choice=>safe(choice.label)).join(' · '):'No tenemos suficientes preferencias para ordenarlas.'}</span></div><p class="quiz-first"><strong>Primera prueba:</strong> ${safe(job.first)}</p><div class="quiz-result-actions"><a href="${jobUrl(job)}">Ver ficha ↗</a><button data-choose="${job.id}" ${chosen.size===2&&!chosen.has(job.id)?'disabled':''}>${chosen.has(job.id)?'− Quitar':'＋ Comparar'}</button></div></article>`).join('')}</div><div class="quiz-end"><button data-quiz-restart>Empezar de nuevo</button><a href="/explorar/">Ver todas las profesiones ↗</a></div><p class="catalog-note">Sugerencias orientativas. La herramienta no guarda tus respuestas ni sustituye a un orientador.</p></section>`}const question=quizQuestions[step];return `<section class="section page-view quiz-view"><div class="quiz-shell"><div class="quiz-meta"><span>Pregunta ${step+1} de ${quizQuestions.length}</span><span>Descubridor de profesiones</span></div><div class="quiz-progress" aria-label="Progreso: ${step+1} de ${quizQuestions.length}"><i style="width:${(step+1)/quizQuestions.length*100}%"></i></div><p class="eyebrow">ELIGE LO QUE MÁS SE ACERQUE A TI</p><h1>${question.title}</h1><div class="quiz-options">${question.options.map((option,index)=>`<button data-quiz-answer="${index}"><span>${safe(option.label)}</span><span aria-hidden="true">↗</span></button>`).join('')}</div><div class="quiz-controls"><button data-quiz-back ${step===0?'disabled':''}>← Volver</button><button data-quiz-skip>No lo sé</button></div><p class="quiz-privacy">Tus respuestas se quedan en esta página.</p></div></section>`}
function centers(){const total=mock.reduce((sum,row)=>sum+row.views,0);return `<section class="section page-view centers-page"><div class="page-heading"><p class="eyebrow">PARA CENTROS</p><h1>Intereses en conjunto</h1><p>Un ejemplo de lo que un centro podría consultar.</p></div><div class="mock-banner"><strong>Datos simulados</strong><span>Esta pantalla no refleja visitas reales ni datos de alumnos.</span></div><div class="dashboard-grid"><article class="stat-card"><span>Consultas de fichas</span><strong>${total}</strong><small>Ejemplo · últimos 30 días</small></article><article class="stat-card"><span>Sectores explorados</span><strong>9</strong><small>Interés repartido entre áreas</small></article><article class="stat-card"><span>Opciones comparadas</span><strong>86</strong><small>Comparaciones iniciadas</small></article></div><div class="insight-grid"><article class="insight-panel"><div class="panel-title"><h2>Interés por sector</h2><span>Consultas</span></div><div class="bars">${mock.map(row=>`<div class="bar-row"><span>${safe(row.name)}</span><div class="bar-track"><i style="width:${Math.round(row.views/mock[0].views*100)}%"></i></div><strong>${row.views}</strong></div>`).join('')}</div><p class="panel-note">Las categorías pequeñas se reúnen en “Otros sectores”.</p></article><article class="insight-panel"><div class="panel-title"><h2>Fichas más vistas</h2><span>Ejemplo</span></div><ol class="rank-list"><li><span>Enfermería</span><strong>72</strong></li><li><span>Desarrollo de software</span><strong>61</strong></li><li><span>Docencia de primaria</span><strong>45</strong></li><li><span>Electricista</span><strong>38</strong></li></ol><p class="panel-note">Sirve para detectar interés, no para evaluar a nadie.</p></article></div><div class="privacy-panel"><div><h2>Qué podríamos medir</h2><p>Fichas consultadas, sectores elegidos y comparaciones. Solo recuentos agregados, sin nombres ni historiales individuales.</p></div><div><h2>Qué no hacemos hoy</h2><p>Este MVP no recopila eventos. Antes de medir habría que definir privacidad, informar claramente y proteger especialmente a menores.</p></div></div></section>`}
function currentRoute(){const path=location.pathname;return path.startsWith('/explorar')?'explorar':path.startsWith('/profesion')?'profesion':path.startsWith('/descubrir')?'descubrir':path.startsWith('/comparar')?'comparar':path.startsWith('/centros')?'centros':path.startsWith('/recursos')||path.startsWith('/criterios')?'recursos':'inicio'}
function render(){const route=currentRoute();const job=route==='profesion'?jobs.find(item=>item.id===new URLSearchParams(location.search).get('id')):null;const views={inicio:home,explorar:explorer,profesion:()=>detail(job),comparar:comparison,descubrir:discover,centros:centers,recursos:resources};app.innerHTML=views[route]();document.title=`${route==='inicio'?'Inicio':route==='profesion'?(job?.name||'Ficha'):route==='explorar'?'Profesiones':route==='comparar'?'Comparar':route==='descubrir'?'Descubrir':route==='centros'?'Para centros':'Recursos'} · Brújula`;document.querySelectorAll('[data-nav]').forEach(link=>link.setAttribute('aria-current',link.dataset.nav===route?'page':'false'));const navCount=document.querySelector('#nav-count');navCount.textContent=chosen.size;navCount.hidden=chosen.size===0;if(route==='explorar')renderResults()}
function renderResults(){const found=filteredJobs();document.querySelector('#cards').innerHTML=found.map(tile).join('');document.querySelector('#count').textContent=`${found.length} ${found.length===1?'profesión':'profesiones'}`;document.querySelector('#empty').hidden=found.length!==0;document.querySelector('#inline-count').textContent=`(${chosen.size})`}
function navigate(url){if(url===location.pathname+location.search)return;const update=()=>{history.pushState({},'',url);render();scrollTo(0,0);app.focus({preventScroll:true})};if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches)document.startViewTransition(update);else update()}
document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(link&&link.origin===location.origin&&!event.metaKey&&!event.ctrlKey&&!event.shiftKey&&!event.altKey&&link.target!=='_blank'){event.preventDefault();navigate(link.pathname+link.search);return}const answer=event.target.closest('[data-quiz-answer]');if(answer){quizState.answers[quizState.step]=quizQuestions[quizState.step].options[Number(answer.dataset.quizAnswer)];quizState.step++;render();scrollTo(0,0);return}if(event.target.closest('[data-quiz-skip]')){quizState.answers[quizState.step]={label:'No lo sé',tags:[]};quizState.step++;render();scrollTo(0,0);return}if(event.target.closest('[data-quiz-back]')){quizState.step=Math.max(0,quizState.step-1);render();return}if(event.target.closest('[data-quiz-restart]')){quizState.step=0;quizState.answers=[];render();scrollTo(0,0);return}const button=event.target.closest('[data-choose]');if(button){const id=button.dataset.choose;if(chosen.has(id))chosen.delete(id);else if(chosen.size<2)chosen.add(id);render()}});
document.addEventListener('input',event=>{if(event.target.id==='search'){filters.query=event.target.value;renderResults()}});
document.addEventListener('change',event=>{if(event.target.id==='sector'||event.target.id==='stage'){filters[event.target.id]=event.target.value;renderResults()}});
addEventListener('popstate',()=>{render();scrollTo(0,0)});
render();
